package com.burningwoman;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class BurnStatsOverlay extends OverlayPanel
{
	private static final Color FLAME_ORANGE = new Color(255, 120, 30);

	private final BurningWomanConfig config;
	private final BurnedTileStore store;

	@Inject
	BurnStatsOverlay(BurningWomanConfig config, BurnedTileStore store)
	{
		this.config = config;
		this.store = store;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showStatsOverlay())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Burning Woman")
			.color(FLAME_ORANGE)
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Tiles burned")
			.right(Integer.toString(store.getTotalBurned()))
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("This session")
			.right(Integer.toString(store.getSessionBurned()))
			.build());

		return super.render(graphics);
	}
}

package com.burningwoman;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class BurnedTileMinimapOverlay extends Overlay
{
	private static final int MAX_DRAW_DISTANCE = 16;
	private static final int TILE_SIZE = 3;

	private final Client client;
	private final BurningWomanConfig config;
	private final BurnedTileStore store;

	@Inject
	BurnedTileMinimapOverlay(Client client, BurningWomanConfig config, BurnedTileStore store)
	{
		this.client = client;
		this.config = config;
		this.store = store;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.drawTilesOnMinimap())
		{
			return null;
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		WorldPoint playerPoint = player.getWorldLocation();
		for (WorldPoint point : store.getSceneBurnedTiles())
		{
			if (point.getPlane() != playerPoint.getPlane() || point.distanceTo(playerPoint) >= MAX_DRAW_DISTANCE)
			{
				continue;
			}

			LocalPoint localPoint = LocalPoint.fromWorld(client, point);
			if (localPoint == null)
			{
				continue;
			}

			Point minimapPoint = Perspective.localToMinimap(client, localPoint);
			if (minimapPoint != null)
			{
				OverlayUtil.renderMinimapRect(client, graphics, minimapPoint, TILE_SIZE, TILE_SIZE, config.markerBorderColor());
			}
		}

		return null;
	}
}

package com.burningwoman;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class BurnedTileOverlay extends Overlay
{
	private static final int MAX_DRAW_DISTANCE = 32;
	private static final Stroke BORDER_STROKE = new BasicStroke(2);

	private final Client client;
	private final BurningWomanConfig config;
	private final BurnedTileStore store;
	private final PreservedFireManager fireManager;

	@Inject
	BurnedTileOverlay(Client client, BurningWomanConfig config, BurnedTileStore store, PreservedFireManager fireManager)
	{
		this.client = client;
		this.config = config;
		this.store = store;
		this.fireManager = fireManager;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		WorldPoint playerPoint = player.getWorldLocation();
		boolean hideUnderFlames = config.hideMarkerUnderFlames() && config.preservedFlames();

		for (WorldPoint point : store.getSceneBurnedTiles())
		{
			if (point.getPlane() != playerPoint.getPlane()
				|| point.distanceTo(playerPoint) >= MAX_DRAW_DISTANCE
				|| (hideUnderFlames && fireManager.hasFlameAt(point)))
			{
				continue;
			}

			LocalPoint localPoint = LocalPoint.fromWorld(client, point);
			if (localPoint == null)
			{
				continue;
			}

			Polygon poly = Perspective.getCanvasTilePoly(client, localPoint);
			if (poly != null)
			{
				OverlayUtil.renderPolygon(graphics, poly, config.markerBorderColor(), config.markerFillColor(), BORDER_STROKE);
			}
		}

		return null;
	}
}

package com.burningwoman;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Base64;
import java.util.BitSet;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;

/**
 * Persists burned tiles as one 4096-bit BitSet per region+plane
 * (64x64 tiles), the same scheme Tileman Mode uses. Also keeps an
 * in-memory cache of every burned region plus the set of burned
 * WorldPoints in the currently loaded scene for rendering.
 */
@Slf4j
@Singleton
public class BurnedTileStore
{
	static final String REGION_KEY_PREFIX = "burned_";
	private static final int REGION_SIZE = 64;

	private final Client client;
	private final ConfigManager configManager;
	private final Gson gson;

	// key = (regionId << 2) | plane
	private final Map<Integer, BitSet> regionTiles = new HashMap<>();
	private final Set<WorldPoint> sceneTiles = new HashSet<>();

	@Getter
	private int totalBurned;
	@Getter
	private int sessionBurned;

	@Inject
	BurnedTileStore(Client client, ConfigManager configManager, Gson gson)
	{
		this.client = client;
		this.configManager = configManager;
		this.gson = gson;
	}

	void loadAll()
	{
		regionTiles.clear();
		totalBurned = 0;

		List<String> keys = configManager.getConfigurationKeys(BurningWomanConfig.GROUP + "." + REGION_KEY_PREFIX);
		for (String fullKey : keys)
		{
			String key = fullKey.substring(fullKey.indexOf('.') + 1);
			String[] parts = key.split("_");
			if (parts.length != 3)
			{
				continue;
			}

			int regionId;
			int plane;
			try
			{
				regionId = Integer.parseInt(parts[1]);
				plane = Integer.parseInt(parts[2]);
			}
			catch (NumberFormatException e)
			{
				log.warn("Ignoring malformed region key {}", fullKey);
				continue;
			}

			String value = configManager.getConfiguration(BurningWomanConfig.GROUP, key);
			if (value == null || value.isEmpty())
			{
				continue;
			}

			BitSet bits = BitSet.valueOf(Base64.getUrlDecoder().decode(value));
			regionTiles.put(cacheKey(regionId, plane), bits);
			totalBurned += bits.cardinality();
		}

		log.debug("Loaded {} burned tiles across {} region planes", totalBurned, regionTiles.size());
	}

	/**
	 * Marks a tile burned and persists it. Must be called on the client thread
	 * with template (non-instance) world coordinates.
	 *
	 * @return true if the tile was newly burned
	 */
	boolean markBurned(WorldPoint point)
	{
		int regionId = point.getRegionID();
		int plane = point.getPlane();
		int index = point.getRegionY() * REGION_SIZE + point.getRegionX();

		BitSet bits = regionTiles.computeIfAbsent(cacheKey(regionId, plane), k -> new BitSet(REGION_SIZE * REGION_SIZE));
		if (bits.get(index))
		{
			return false;
		}

		bits.set(index);
		configManager.setConfiguration(BurningWomanConfig.GROUP, regionKey(regionId, plane), bits.toByteArray());
		totalBurned++;
		sessionBurned++;
		sceneTiles.addAll(WorldPoint.toLocalInstance(client, point));
		return true;
	}

	/**
	 * Rebuilds the set of burned tiles in the loaded scene. Must be called on
	 * the client thread after the scene has loaded.
	 */
	void rebuildSceneCache()
	{
		sceneTiles.clear();
		for (int regionId : client.getMapRegions())
		{
			for (int plane = 0; plane < 4; plane++)
			{
				BitSet bits = regionTiles.get(cacheKey(regionId, plane));
				if (bits == null)
				{
					continue;
				}

				for (int i = bits.nextSetBit(0); i >= 0; i = bits.nextSetBit(i + 1))
				{
					int regionY = i / REGION_SIZE;
					int regionX = i % REGION_SIZE;
					WorldPoint template = WorldPoint.fromRegion(regionId, regionX, regionY, plane);
					sceneTiles.addAll(WorldPoint.toLocalInstance(client, template));
				}
			}
		}
	}

	void clearSceneCache()
	{
		sceneTiles.clear();
	}

	/**
	 * Burned tiles in the loaded scene, in scene (instance-translated)
	 * coordinates, all planes.
	 */
	Set<WorldPoint> getSceneBurnedTiles()
	{
		return Collections.unmodifiableSet(sceneTiles);
	}

	/**
	 * All burned regions, for the world map overlay. Key = (regionId << 2) | plane.
	 */
	Map<Integer, BitSet> getAllBurnedRegions()
	{
		return Collections.unmodifiableMap(regionTiles);
	}

	/**
	 * Serializes every burned tile for the current profile into a portable
	 * JSON document.
	 */
	String exportToJson()
	{
		TileExport export = new TileExport();
		export.regions = new ArrayList<>();
		for (Map.Entry<Integer, BitSet> entry : regionTiles.entrySet())
		{
			RegionExport region = new RegionExport();
			region.regionId = entry.getKey() >> 2;
			region.plane = entry.getKey() & 0x3;
			region.bits = Base64.getUrlEncoder().encodeToString(entry.getValue().toByteArray());
			export.regions.add(region);
		}

		return gson.toJson(export);
	}

	/**
	 * Merges burned tiles from a previously exported JSON document into the
	 * current profile, persisting any newly burned regions. Must be called
	 * on the client thread.
	 *
	 * @return the number of tiles newly burned by the import
	 * @throws com.google.gson.JsonSyntaxException if the document isn't a Burning Woman export
	 */
	int importFromJson(String json)
	{
		TileExport export = gson.fromJson(json, TileExport.class);
		if (export == null || export.regions == null || export.version != TileExport.VERSION)
		{
			log.warn("Ignoring tile import with unsupported version");
			return 0;
		}

		int imported = 0;
		for (RegionExport region : export.regions)
		{
			if (region.bits == null || region.plane < 0 || region.plane > 3)
			{
				log.warn("Ignoring malformed exported region {}_{}", region.regionId, region.plane);
				continue;
			}

			BitSet incoming;
			try
			{
				incoming = BitSet.valueOf(Base64.getUrlDecoder().decode(region.bits));
			}
			catch (IllegalArgumentException e)
			{
				log.warn("Ignoring malformed exported region {}_{}", region.regionId, region.plane);
				continue;
			}

			BitSet newlySet = (BitSet) incoming.clone();
			int key = cacheKey(region.regionId, region.plane);
			BitSet bits = regionTiles.computeIfAbsent(key, k -> new BitSet(REGION_SIZE * REGION_SIZE));
			newlySet.andNot(bits);
			if (newlySet.isEmpty())
			{
				continue;
			}

			bits.or(incoming);
			configManager.setConfiguration(BurningWomanConfig.GROUP, regionKey(region.regionId, region.plane), bits.toByteArray());
			imported += newlySet.cardinality();
		}

		totalBurned += imported;
		if (imported > 0 && client.getGameState() == GameState.LOGGED_IN)
		{
			rebuildSceneCache();
		}

		log.debug("Imported {} newly burned tiles", imported);
		return imported;
	}

	/**
	 * Clears every burned tile for the current profile, in memory and in
	 * persisted config. Must be called on the client thread.
	 */
	void resetAll()
	{
		List<String> keys = configManager.getConfigurationKeys(BurningWomanConfig.GROUP + "." + REGION_KEY_PREFIX);
		for (String fullKey : keys)
		{
			String key = fullKey.substring(fullKey.indexOf('.') + 1);
			configManager.unsetConfiguration(BurningWomanConfig.GROUP, key);
		}

		regionTiles.clear();
		sceneTiles.clear();
		totalBurned = 0;
		sessionBurned = 0;

		log.debug("Reset all burned tiles for the current profile");
	}

	static int cacheKey(int regionId, int plane)
	{
		return (regionId << 2) | plane;
	}

	private static String regionKey(int regionId, int plane)
	{
		return REGION_KEY_PREFIX + regionId + "_" + plane;
	}

	private static final class TileExport
	{
		static final int VERSION = 1;

		int version = VERSION;
		List<RegionExport> regions;
	}

	private static final class RegionExport
	{
		int regionId;
		int plane;
		String bits;
	}
}

package com.burningwoman;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.BitSet;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.worldmap.WorldMapOverlay;

/**
 * Fills burned tiles on the world map — the series' coverage map. Tiles from
 * all planes are unioned, since the world map only depicts the surface.
 */
public class BurnedTileWorldMapOverlay extends Overlay
{
	private static final int REGION_SIZE = 64;

	private final Client client;
	private final BurningWomanConfig config;
	private final BurnedTileStore store;
	private final WorldMapOverlay worldMapOverlay;

	@Inject
	BurnedTileWorldMapOverlay(Client client, BurningWomanConfig config, BurnedTileStore store, WorldMapOverlay worldMapOverlay)
	{
		this.client = client;
		this.config = config;
		this.store = store;
		this.worldMapOverlay = worldMapOverlay;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_HIGHEST);
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.WORLDMAP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.drawTilesOnWorldMap())
		{
			return null;
		}

		Widget mapWidget = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (mapWidget == null || mapWidget.isHidden())
		{
			return null;
		}

		Rectangle mapBounds = mapWidget.getBounds();
		Shape oldClip = graphics.getClip();
		graphics.clip(mapBounds);

		float pixelsPerTile = client.getWorldMap().getWorldMapZoom();
		int tileSize = Math.max(1, Math.round(pixelsPerTile));
		Color color = config.markerBorderColor();
		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue()));

		for (Map.Entry<Integer, BitSet> entry : store.getAllBurnedRegions().entrySet())
		{
			int regionId = entry.getKey() >> 2;
			int baseX = ((regionId >> 8) & 0xFF) << 6;
			int baseY = (regionId & 0xFF) << 6;

			// Skip regions that are entirely off the visible map.
			Point corner1 = worldMapOverlay.mapWorldPointToGraphicsPoint(new WorldPoint(baseX, baseY, 0));
			Point corner2 = worldMapOverlay.mapWorldPointToGraphicsPoint(new WorldPoint(baseX + REGION_SIZE, baseY + REGION_SIZE, 0));
			if (corner1 == null || corner2 == null
				|| !mapBounds.intersects(new Rectangle(
					Math.min(corner1.getX(), corner2.getX()) - tileSize,
					Math.min(corner1.getY(), corner2.getY()) - tileSize,
					Math.abs(corner2.getX() - corner1.getX()) + 2 * tileSize,
					Math.abs(corner2.getY() - corner1.getY()) + 2 * tileSize)))
			{
				continue;
			}

			BitSet bits = entry.getValue();
			for (int i = bits.nextSetBit(0); i >= 0; i = bits.nextSetBit(i + 1))
			{
				int x = baseX + (i % REGION_SIZE);
				int y = baseY + (i / REGION_SIZE);
				Point tilePoint = worldMapOverlay.mapWorldPointToGraphicsPoint(new WorldPoint(x, y, 0));
				if (tilePoint != null)
				{
					graphics.fillRect(tilePoint.getX() - tileSize / 2, tilePoint.getY() - tileSize / 2, tileSize, tileSize);
				}
			}
		}

		graphics.setClip(oldClip);
		return null;
	}
}

package com.burningwoman;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(BurningWomanConfig.GROUP)
public interface BurningWomanConfig extends Config
{
	String GROUP = "burningwoman";

	@ConfigSection(
		name = "Tile markers",
		description = "How burned tiles are marked",
		position = 0
	)
	String markerSection = "markers";

	@ConfigSection(
		name = "Preserved flames",
		description = "Animated fires re-lit on tiles you have burned",
		position = 1
	)
	String flameSection = "flames";

	@Alpha
	@ConfigItem(
		keyName = "markerBorderColor",
		name = "Border color",
		description = "Border color of burned tile markers",
		section = markerSection,
		position = 0
	)
	default Color markerBorderColor()
	{
		return new Color(255, 120, 30, 190);
	}

	@Alpha
	@ConfigItem(
		keyName = "markerFillColor",
		name = "Fill color",
		description = "Fill color of burned tile markers",
		section = markerSection,
		position = 1
	)
	default Color markerFillColor()
	{
		return new Color(255, 90, 0, 50);
	}

	@ConfigItem(
		keyName = "drawTilesOnMinimap",
		name = "Show on minimap",
		description = "Draw burned tiles on the minimap",
		section = markerSection,
		position = 2
	)
	default boolean drawTilesOnMinimap()
	{
		return true;
	}

	@ConfigItem(
		keyName = "drawTilesOnWorldMap",
		name = "Show on world map",
		description = "Draw burned tiles on the world map",
		section = markerSection,
		position = 3
	)
	default boolean drawTilesOnWorldMap()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showStatsOverlay",
		name = "Show stats overlay",
		description = "Show the burned tile counters",
		section = markerSection,
		position = 4
	)
	default boolean showStatsOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "preservedFlames",
		name = "Preserved flames",
		description = "Render an animated fire on burned tiles near you, even after the real fire went out",
		section = flameSection,
		position = 0
	)
	default boolean preservedFlames()
	{
		return true;
	}

	@Range(min = 1, max = 64)
	@Units(" tiles")
	@ConfigItem(
		keyName = "flameRadius",
		name = "Flame radius",
		description = "Only render preserved flames within this distance of you",
		section = flameSection,
		position = 1
	)
	default int flameRadius()
	{
		return 24;
	}

	@Range(min = 1, max = 256)
	@ConfigItem(
		keyName = "maxFlames",
		name = "Max flames",
		description = "Upper bound on simultaneously rendered flames (closest first)",
		section = flameSection,
		position = 2
	)
	default int maxFlames()
	{
		return 64;
	}

	@ConfigItem(
		keyName = "hideMarkerUnderFlames",
		name = "Hide marker under flames",
		description = "Don't draw the flat tile marker on tiles that currently show a preserved flame",
		section = flameSection,
		position = 3
	)
	default boolean hideMarkerUnderFlames()
	{
		return true;
	}
}

package com.burningwoman;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Burning Woman",
	description = "Tileman-style tracker where tiles are claimed by lighting fires on them",
	tags = {"firemaking", "tiles", "tileman", "overlay"}
)
public class BurningWomanPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventBus eventBus;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private BurningWomanPluginPanel panel;

	@Inject
	private BurnedTileStore store;

	@Inject
	private FireLightingDetector detector;

	@Inject
	private PreservedFireManager fireManager;

	@Inject
	private BurnedTileOverlay tileOverlay;

	@Inject
	private BurnedTileMinimapOverlay minimapOverlay;

	@Inject
	private BurnedTileWorldMapOverlay worldMapOverlay;

	@Inject
	private BurnStatsOverlay statsOverlay;

	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		store.loadAll();
		eventBus.register(detector);
		eventBus.register(fireManager);
		overlayManager.add(tileOverlay);
		overlayManager.add(minimapOverlay);
		overlayManager.add(worldMapOverlay);
		overlayManager.add(statsOverlay);

		navButton = NavigationButton.builder()
			.tooltip("Burning Woman")
			.icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				store.rebuildSceneCache();
				detector.initXpBaseline();
			}
		});

		log.debug("Burning Woman started with {} burned tiles", store.getTotalBurned());
	}

	@Override
	protected void shutDown()
	{
		eventBus.unregister(detector);
		eventBus.unregister(fireManager);
		overlayManager.remove(tileOverlay);
		overlayManager.remove(minimapOverlay);
		overlayManager.remove(worldMapOverlay);
		overlayManager.remove(statsOverlay);
		clientToolbar.removeNavigation(navButton);
		detector.reset();
		clientThread.invoke(fireManager::clearAll);
		store.clearSceneCache();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			store.rebuildSceneCache();
		}
	}

	@Provides
	BurningWomanConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BurningWomanConfig.class);
	}
}

