import com.google.gson.JsonSyntaxException;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JFileChooser;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.filechooser.FileNameExtensionFilter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * Side panel for backing up, restoring, and wiping this profile's burned
 * tiles. File IO runs on the shared executor and mutations to
 * {@link BurnedTileStore} are always marshalled onto the client thread,
 * since the store's collections are read from overlays every frame.
 */
@Slf4j
class BurningWomanPluginPanel extends PluginPanel
{
	private final ClientThread clientThread;
	private final BurnedTileStore store;
	private final ScheduledExecutorService executor;

	private final JLabel statusLabel = new JLabel();

	@Inject
	BurningWomanPluginPanel(ClientThread clientThread, BurnedTileStore store, ScheduledExecutorService executor)
	{
		this.clientThread = clientThread;
		this.store = store;
		this.executor = executor;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		statusLabel.setForeground(Color.WHITE);
		statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		JButton exportButton = new JButton("Export tiles...");
		exportButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		exportButton.addActionListener(e -> exportTiles());

		JButton importButton = new JButton("Import tiles...");
		importButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		importButton.addActionListener(e -> importTiles());

		JButton resetButton = new JButton("Reset burned tiles...");
		resetButton.setForeground(Color.WHITE);
		resetButton.setBackground(new Color(150, 30, 30));
		resetButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		resetButton.addActionListener(e -> resetTiles());

		content.add(statusLabel);
		content.add(Box.createRigidArea(new Dimension(0, 10)));
		content.add(exportButton);
		content.add(Box.createRigidArea(new Dimension(0, 6)));
		content.add(importButton);
		content.add(Box.createRigidArea(new Dimension(0, 16)));
		content.add(resetButton);

		add(content, BorderLayout.NORTH);
	}

	@Override
	public void onActivate()
	{
		refreshStatus();
	}

	private void refreshStatus()
	{
		statusLabel.setText("<html>" + store.getTotalBurned() + " tile(s) burned<br/>on this profile</html>");
	}

	private void exportTiles()
	{
		JFileChooser chooser = new JFileChooser();
		chooser.setSelectedFile(new File("burning-woman-tiles.json"));
		chooser.setFileFilter(new FileNameExtensionFilter("JSON files", "json"));
		if (chooser.showSaveDialog(this) != JFileChooser.APPROVE_OPTION)
		{
			return;
		}

		File file = chooser.getSelectedFile();
		clientThread.invoke(() ->
		{
			String json = store.exportToJson();
			executor.execute(() ->
			{
				try
				{
					Files.write(file.toPath(), json.getBytes(StandardCharsets.UTF_8));
					SwingUtilities.invokeLater(() -> showInfo("Exported tiles to " + file.getName()));
				}
				catch (IOException e)
				{
					log.warn("Failed to export burned tiles", e);
					SwingUtilities.invokeLater(() -> showError("Failed to export tiles: " + e.getMessage()));
				}
			});
		});
	}

	private void importTiles()
	{
		JFileChooser chooser = new JFileChooser();
		chooser.setFileFilter(new FileNameExtensionFilter("JSON files", "json"));
		if (chooser.showOpenDialog(this) != JFileChooser.APPROVE_OPTION)
		{
			return;
		}

		File file = chooser.getSelectedFile();
		executor.execute(() ->
		{
			String json;
			try
			{
				json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
			}
			catch (IOException e)
			{
				log.warn("Failed to read tile import file", e);
				SwingUtilities.invokeLater(() -> showError("Failed to read file: " + e.getMessage()));
				return;
			}

			clientThread.invoke(() ->
			{
				int imported;
				try
				{
					imported = store.importFromJson(json);
				}
				catch (JsonSyntaxException e)
				{
					log.warn("Failed to parse tile import file", e);
					SwingUtilities.invokeLater(() -> showError("That file isn't a valid Burning Woman export."));
					return;
				}

				int count = imported;
				SwingUtilities.invokeLater(() ->
				{
					refreshStatus();
					showInfo("Imported " + count + " newly burned tile(s).");
				});
			});
		});
	}

	private void resetTiles()
	{
		int confirm = JOptionPane.showConfirmDialog(this,
			"This will permanently delete all burned tiles for the current profile. This cannot be undone.\nContinue?",
			"Reset burned tiles", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
		if (confirm != JOptionPane.YES_OPTION)
		{
			return;
		}

		clientThread.invoke(() ->
		{
			store.resetAll();
			SwingUtilities.invokeLater(this::refreshStatus);
		});
	}

	private void showInfo(String message)
	{
		JOptionPane.showMessageDialog(this, message, "Burning Woman", JOptionPane.INFORMATION_MESSAGE);
	}

	private void showError(String message)
	{
		JOptionPane.showMessageDialog(this, message, "Burning Woman", JOptionPane.ERROR_MESSAGE);
	}
}

package com.burningwoman;

import com.google.common.collect.ImmutableSet;
import java.util.Set;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ObjectID;

final class FireIds
{
	/**
	 * Scenery objects spawned when a player lights logs on the ground.
	 * Colored variants come from colored/trailblazer logs; all share the
	 * same model with recolors applied.
	 */
	static final Set<Integer> FIRE_OBJECTS = ImmutableSet.of(
		ObjectID.FIRE,
		ObjectID.RED_FIRE,
		ObjectID.GREEN_FIRE,
		ObjectID.BLUE_FIRE,
		ObjectID.TRAIL_WHITE_FIRE,
		ObjectID.TRAIL_PURPLE_FIRE
	);

	/**
	 * Player animations that light a fire on the ground: tinderbox lighting
	 * plus the barbarian bow-lighting animation for each bow type.
	 */
	static final Set<Integer> LIGHTING_ANIMATIONS = ImmutableSet.of(
		AnimationID.HUMAN_CREATEFIRE,
		AnimationID.BRUT_PLAYER_FIREMAKING_AIDE_SHORTBOW,
		AnimationID.BRUT_PLAYER_FIREMAKING_SHORTBOW,
		AnimationID.BRUT_PLAYER_FIREMAKING_OAK_SHORTBOW,
		AnimationID.BRUT_PLAYER_FIREMAKING_WILLOW_SHORTBOW,
		AnimationID.BRUT_PLAYER_FIREMAKING_MAPLE_SHORTBOW,
		AnimationID.BRUT_PLAYER_FIREMAKING_YEW_SHORTBOW,
		AnimationID.BRUT_PLAYER_FIREMAKING_MAGIC_SHORTBOW,
		AnimationID.BRUT_PLAYER_FIREMAKING_DAGANOTH_BOW
	);

	// The fire scenery (ObjectID.FIRE) uses model 2260 animated by seq 475.
	// These are cache values not exposed through the RuneLite API.
	static final int FIRE_MODEL = 2260;
	static final int FIRE_ANIMATION = 475;

	static final String FIRE_LIT_MESSAGE = "The fire catches and the logs begin to burn.";

	private FireIds()
	{
	}
}

package com.burningwoman;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Attributes fire objects to the local player. A tile is burned when all of:
 * the local player performed a lighting animation on it, a fire object
 * spawned on it shortly after, and a Firemaking confirmation (XP drop or the
 * "fire catches" message) landed within a couple of ticks of the spawn.
 * The tile match plus confirmation prevents claiming other players' fires.
 */
@Slf4j
@Singleton
class FireLightingDetector
{
	private static final int FIRE_SPAWN_WINDOW_TICKS = 5;
	private static final int CONFIRM_WINDOW_TICKS = 2;
	private static final int NEVER = -1000;

	private final Client client;
	private final BurnedTileStore store;

	private WorldPoint lightingTile;
	private int lightingTick = NEVER;
	private WorldPoint spawnedFireTile;
	private int fireSpawnTick = NEVER;
	private int confirmTick = NEVER;
	private long lastFiremakingXp = -1;

	@Inject
	FireLightingDetector(Client client, BurnedTileStore store)
	{
		this.client = client;
		this.store = store;
	}

	void reset()
	{
		lightingTile = null;
		lightingTick = NEVER;
		spawnedFireTile = null;
		fireSpawnTick = NEVER;
		confirmTick = NEVER;
		lastFiremakingXp = -1;
	}

	void initXpBaseline()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			lastFiremakingXp = client.getSkillExperience(Skill.FIREMAKING);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			initXpBaseline();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			reset();
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			recordLightingAttempt();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// The lighting animation persists across attempts; keep the attempt
		// tile fresh in case the player shuffled between attempts.
		recordLightingAttempt();
	}

	private void recordLightingAttempt()
	{
		Player player = client.getLocalPlayer();
		if (player == null || !FireIds.LIGHTING_ANIMATIONS.contains(player.getAnimation()))
		{
			return;
		}

		lightingTile = WorldPoint.fromLocalInstance(client, player.getLocalLocation());
		lightingTick = client.getTickCount();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject object = event.getGameObject();
		if (!FireIds.FIRE_OBJECTS.contains(object.getId()) || lightingTile == null)
		{
			return;
		}

		WorldPoint firePoint = WorldPoint.fromLocalInstance(client, object.getLocalLocation());
		if (firePoint.equals(lightingTile) && client.getTickCount() - lightingTick <= FIRE_SPAWN_WINDOW_TICKS)
		{
			spawnedFireTile = firePoint;
			fireSpawnTick = client.getTickCount();
			tryComplete();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		if (FireIds.FIRE_LIT_MESSAGE.equals(Text.removeTags(event.getMessage())))
		{
			confirmTick = client.getTickCount();
			tryComplete();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.FIREMAKING)
		{
			return;
		}

		long xp = event.getXp();
		if (lastFiremakingXp >= 0 && xp > lastFiremakingXp)
		{
			confirmTick = client.getTickCount();
			tryComplete();
		}
		lastFiremakingXp = xp;
	}

	private void tryComplete()
	{
		if (spawnedFireTile == null || Math.abs(fireSpawnTick - confirmTick) > CONFIRM_WINDOW_TICKS)
		{
			return;
		}

		if (store.markBurned(spawnedFireTile))
		{
			log.debug("Burned tile {} (total {})", spawnedFireTile, store.getTotalBurned());
		}
		spawnedFireTile = null;
		fireSpawnTick = NEVER;
	}
}

package com.burningwoman;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;

/**
 * Re-lights burned tiles with animated fire models (RuneLiteObjects).
 * Keeps only the nearest tiles within the configured radius alight, capped
 * at a maximum, and yields to real fires currently burning on a tile.
 * RuneLiteObjects don't survive scene reloads, so everything is rebuilt
 * from {@link BurnedTileStore}'s scene cache after each load.
 */
@Slf4j
@Singleton
public class PreservedFireManager
{
	private final Client client;
	private final BurningWomanConfig config;
	private final BurnedTileStore store;
	private final Random random = new Random();

	// scene coordinates -> spawned flame
	private final Map<WorldPoint, RuneLiteObject> flames = new HashMap<>();
	// scene coordinates of real fire objects currently burning
	private final Set<WorldPoint> realFires = new HashSet<>();

	private Animation fireAnimation;

	@Inject
	PreservedFireManager(Client client, BurningWomanConfig config, BurnedTileStore store)
	{
		this.client = client;
		this.config = config;
		this.store = store;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			// The scene is being torn down; our objects and the real-fire
			// positions are invalid in the new scene.
			clearAll();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject object = event.getGameObject();
		if (!FireIds.FIRE_OBJECTS.contains(object.getId()))
		{
			return;
		}

		WorldPoint point = object.getWorldLocation();
		realFires.add(point);

		// A real fire takes precedence over our preserved flame.
		RuneLiteObject flame = flames.remove(point);
		if (flame != null)
		{
			flame.setActive(false);
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		if (FireIds.FIRE_OBJECTS.contains(event.getGameObject().getId()))
		{
			// update() re-lights the tile on the next tick if it's burned.
			realFires.remove(event.getGameObject().getWorldLocation());
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		update();
	}

	void update()
	{
		if (!config.preservedFlames() || client.getGameState() != GameState.LOGGED_IN)
		{
			clearFlames();
			return;
		}

		Player player = client.getLocalPlayer();
		if (player == null || !ensureResources())
		{
			return;
		}

		WorldPoint playerPoint = player.getWorldLocation();
		int radius = config.flameRadius();

		List<WorldPoint> candidates = new ArrayList<>();
		for (WorldPoint point : store.getSceneBurnedTiles())
		{
			if (point.getPlane() == playerPoint.getPlane()
				&& point.distanceTo(playerPoint) <= radius
				&& !realFires.contains(point))
			{
				candidates.add(point);
			}
		}

		candidates.sort(Comparator.comparingInt(playerPoint::distanceTo));
		Set<WorldPoint> desired = new HashSet<>(candidates.subList(0, Math.min(candidates.size(), config.maxFlames())));

		flames.entrySet().removeIf(entry ->
		{
			if (desired.contains(entry.getKey()))
			{
				return false;
			}
			entry.getValue().setActive(false);
			return true;
		});

		for (WorldPoint point : desired)
		{
			if (!flames.containsKey(point))
			{
				spawnFlame(point);
			}
		}
	}

	boolean hasFlameAt(WorldPoint scenePoint)
	{
		return flames.containsKey(scenePoint);
	}

	private boolean ensureResources()
	{
		if (fireAnimation == null)
		{
			fireAnimation = client.loadAnimation(FireIds.FIRE_ANIMATION);
		}
		return fireAnimation != null;
	}

	private void spawnFlame(WorldPoint point)
	{
		LocalPoint localPoint = LocalPoint.fromWorld(client, point);
		if (localPoint == null)
		{
			return;
		}

		// Each flame gets its own Model: the flames animate at different
		// frames, so sharing one base model across objects isn't safe.
		Model model = client.loadModel(FireIds.FIRE_MODEL);
		if (model == null)
		{
			return;
		}

		RuneLiteObject flame = client.createRuneLiteObject();
		flame.setModel(model);
		flame.setAnimation(fireAnimation);
		flame.setShouldLoop(true);
		flame.setLocation(localPoint, point.getPlane());
		flame.setActive(true);

		// Desynchronize the flames so a field of fires doesn't pulse in
		// lockstep.
		AnimationController controller = flame.getAnimationController();
		if (controller != null && fireAnimation.getNumFrames() > 0)
		{
			controller.setFrame(random.nextInt(fireAnimation.getNumFrames()));
		}

		flames.put(point, flame);
	}

	private void clearFlames()
	{
		if (flames.isEmpty())
		{
			return;
		}
		for (RuneLiteObject flame : flames.values())
		{
			flame.setActive(false);
		}
		flames.clear();
	}

	void clearAll()
	{
		clearFlames();
		realFires.clear();
	}
}

